LINK_TEXT = {"nl": "Informatie aanvragen", "en": "Request information", "de": "Informationen anfordern"}


def add_info_links(apps, schema_editor):
    """The default blocks without a link (Service packs, Spare parts) get an email link for information."""
    HomeBlock = apps.get_model("siteconfig", "HomeBlock")
    for block in HomeBlock.objects.filter(title_nl__in=["Servicepacks", "Onderdelen"], link_url=""):
        block.link_url = "mailto:"
        block.link_text = LINK_TEXT["nl"]
        for lang, text in LINK_TEXT.items():
            setattr(block, f"link_text_{lang}", text)
        block.save()


